// Fast index lookups
const actByIdMap = new Map<string, ActManifestItem>();
const actByTitleMap = new Map<string, ActManifestItem>();
const actByShortCodeMap = new Map<string, ActManifestItem>();

for (const act of ACTS_MANIFEST) {
  actByIdMap.set(act.id.toLowerCase(), act);
  actByTitleMap.set(act.title.toLowerCase(), act);
  if (act.shortCode) {
    actByShortCodeMap.set(act.shortCode.toLowerCase(), act);
  }
}

export function getActManifestById(id: string): ActManifestItem | undefined {
  return actByIdMap.get(id.toLowerCase());
}

export function getActManifestByTitle(title: string): ActManifestItem | undefined {
  return actByTitleMap.get(title.toLowerCase());
}

export function getActManifestByShortCode(shortCode: string): ActManifestItem | undefined {
  return actByShortCodeMap.get(shortCode.toLowerCase());
}

export function getActsByCategory(category: string): ActManifestItem[] {
  const normCat = category.toLowerCase();
  return ACTS_MANIFEST.filter(act => act.category.toLowerCase() === normCat);
}

export function searchActsManifest(query: string, limit: number = 50): ActManifestItem[] {
  if (!query || !query.trim()) return ACTS_MANIFEST.slice(0, limit);
  const q = query.toLowerCase().trim();
  const tokens = q.split(/\s+/);
  
  const results: { act: ActManifestItem; score: number }[] = [];
  
  for (const act of ACTS_MANIFEST) {
    const titleLower = act.title.toLowerCase();
    const shortCodeLower = (act.shortCode || '').toLowerCase();
    let score = 0;
    
    if (shortCodeLower && shortCodeLower === q) {
      score += 1000;
    } else if (shortCodeLower && shortCodeLower.includes(q)) {
      score += 500;
    }
    
    if (titleLower === q) {
      score += 800;
    } else if (titleLower.startsWith(q)) {
      score += 400;
    }
    
    let allTokensMatch = true;
    for (const t of tokens) {
      if (titleLower.includes(t) || shortCodeLower.includes(t) || act.category.includes(t)) {
        score += 50;
      } else {
        allTokensMatch = false;
      }
    }
    
    if (allTokensMatch) {
      score += 100;
    }
    
    if (score > 0) {
      results.push({ act, score });
    }
  }
  
  results.sort((a, b) => b.score - a.score || b.act.sectionCount - a.act.sectionCount);
  return results.slice(0, limit).map(r => r.act);
}

export function getAllCategories(): string[] {
  const cats = new Set<string>();
  for (const act of ACTS_MANIFEST) {
    cats.add(act.category);
  }
  return Array.from(cats).sort();
}
